Lemma pb_call (a ra pv v9 : Z) (fxq : FPState) Rq Mq mdq crq kq :
  inv Mq mdq crq kq a -> 0 <= a -> a + 1 <= w -> L5.ra_ok ra -> sp - 48 <= pv -> pv + 1 <= sp - 24 ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 n -> getr Rq (PMK.reg 9) = Z_to_bv 64 v9 ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (fb + 496) -> getr Rq (PMK.reg 11) = Z_to_bv 64 pv -> csl Rq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, inv M2 md2 cr2 k2 (a + 1) ->
      getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 48) -> getr R2 (PMK.reg 8) = Z_to_bv 64 n -> getr R2 (PMK.reg 9) = Z_to_bv 64 v9 -> csl R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Rq 0x372d8 Mq mdq) K.
